  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original mathematical computation:

     y = A^T * (A * x)

   More explicitly:

     tmp[i] = sum_j A[i,j] * x[j]        (matrix-vector product, A * x)
     y[j]   = sum_i A[i,j] * tmp[i]      (matrix-vector product, A^T * tmp)

   The original reference implementation computed these in a single
   i-loop:

     y[:] = 0;
     for i:
       tmp[i] = 0;
       for j: tmp[i] += A[i,j] * x[j];
       for j: y[j]   += A[i,j] * tmp[i];

   The optimized version below preserves the *per-element* reduction
   order for both tmp[i] and y[j], but restructures the loops to
   improve data locality and expose more opportunities for the compiler
   to vectorize:
     - y is initialized once.
     - tmp = A * x is computed in a separate pass with a scalar
       accumulator kept in a register.
     - y = A^T * tmp is computed with j-tiling so that small slices of
       y and the corresponding columns of A stay hot in cache while we
       sweep across all rows.
*/
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Use local restrict-qualified aliases to help the compiler reason
     about aliasing and generate better vectorized code.  In this
     benchmark, A, x, y, and tmp never alias each other. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE * restrict x_      = x;
  DATA_TYPE * restrict y_      = y;
  DATA_TYPE * restrict tmp_    = tmp;

  const int M = _PB_M;
  const int N = _PB_N;

  /* Tile size along the j (column / vector) dimension used when
     updating y.  256 elements correspond to 2 KiB for doubles,
     which fits comfortably in L1/L2 on modern CPUs.  The value is
     a compile-time constant so the compiler can better unroll and
     vectorize the inner loops. */
  const int TILE_J = 256;

#pragma scop
  /*------------------------------------------------------------------
    1) Initialize y to zero.

       Matches the original:
         for (i = 0; i < _PB_N; i++) y[i] = 0;
  ------------------------------------------------------------------*/
  for (j = 0; j < N; ++j)
    y_[j] = SCALAR_VAL(0.0);

  /*------------------------------------------------------------------
    2) First matrix-vector product: tmp = A * x

       For each row i:
         tmp[i] = sum_{j=0..N-1} A[i,j] * x[j]

       This loop nest is semantically identical to the original tmp
       computation, but uses a scalar accumulator 'sum' kept in a
       register and writes tmp_[i] only once per row, reducing
       memory traffic.
  ------------------------------------------------------------------*/
  for (i = 0; i < M; ++i)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    DATA_TYPE * restrict Ai = A_[i];

    /* Inner loop is unit-stride over j for both A[i][j] and x[j],
       which is ideal for SIMD vectorization. */
    for (j = 0; j < N; ++j)
      sum += Ai[j] * x_[j];

    tmp_[i] = sum;
  }

  /*------------------------------------------------------------------
    3) Second matrix-vector product: y = A^T * tmp

       Mathematically:
         y[j] = sum_{i=0..M-1} A[i,j] * tmp[i]

       A is row-major, so A[i,*] is contiguous in j.  A naive
       implementation

         for (i = 0; i < M; ++i)
           for (j = 0; j < N; ++j)
             y[j] += A[i][j] * tmp[i];

       updates y[j] in the same (i) order as above but repeatedly
       streams the full y-vector for each row i.

       To improve cache locality for y and maintain unit-stride access
       to A, we:
         - Tile the j-dimension into contiguous blocks of size TILE_J.
         - For each tile [jj, j_end), we sweep all rows i and update
           only y[jj..j_end-1].

       For a *fixed* column j, the updates still occur in strictly
       increasing i order (0, 1, ..., M-1), exactly as in the original
       code, so the floating-point reduction order for each y[j] is
       preserved.  Only the interleaving of updates to *different*
       y-elements is changed, which does not affect the result.
  ------------------------------------------------------------------*/
  {
    int jj;
    for (jj = 0; jj < N; jj += TILE_J)
    {
      const int j_end = (jj + TILE_J < N) ? (jj + TILE_J) : N;

      for (i = 0; i < M; ++i)
      {
        const DATA_TYPE t = tmp_[i];
        DATA_TYPE * restrict Ai = A_[i] + jj;

        /* Inner loop walks a contiguous slice of columns, enabling
           good cache behavior and SIMD vectorization for both A and y. */
        for (j = jj; j < j_end; ++j)
        {
          y_[j] += (*Ai) * t;
          ++Ai;
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
