/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation (row-wise formulation):

     y[:] = 0;
     for i in 0..M-1:
       tmp[i] = sum_j A[i,j] * x[j];
       for j in 0..N-1:
         y[j] += A[i,j] * tmp[i];

   Mathematically, this is:
     tmp = A * x
     y   = A^T * tmp = A^T * (A * x)

   The optimized version below keeps the same mathematical result and the
   same final contents of tmp, but restructures the computation into:

     1) tmp = A * x              (row-wise, vectorizable)
     2) y  = A^T * tmp           (j-tiled, row-major traversal of A)

   This improves:
     - cache locality for y (operate on small y-tiles that stay in cache),
     - vectorization and ILP over the contiguous j-dimension,
     - reuse of tmp without repeated loads in inner loops.

   The order of additions contributing to each y[j] over i is preserved,
   so floating-point round-off behavior for each y[j] matches the original
   loop nest.
*/
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Create local restrict-qualified aliases to help the compiler
     with alias analysis and vectorization.  The layout is unchanged:
       - A_ is an m x n row-major matrix,
       - x_, y_ are length-n vectors,
       - tmp_ is a length-m vector. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

  /* Tile size along the j (column / vector) dimension used in the
     y = A^T * tmp phase. This is chosen to keep a slice of y in L1/L2. */
  const int tile_j = 256;

#pragma scop
  /* Initialize y to zero (as in the original kernel). */
  for (j = 0; j < _PB_N; j++)
    y_[j] = SCALAR_VAL(0.0);

  /* --------------------------------------------------------------------
   * Phase 1: tmp = A * x
   *   tmp[i] = sum_j A[i,j] * x[j]
   *
   * This is a row-wise matrix-vector product. The inner j-loop streams
   * through A[i,*] and x[*] with unit stride, which is cache-friendly
   * and amenable to SIMD vectorization. A small manual unroll factor
   * over j exposes more ILP and reduces loop overhead.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE sum = SCALAR_VAL(0.0);
    DATA_TYPE *restrict Ai = A_[i];

    int j_end    = _PB_N;
    int j_vecend = j_end & ~3; /* largest multiple of 4 <= j_end */

    /* Unrolled main loop: process 4 elements per iteration. */
    for (j = 0; j < j_vecend; j += 4)
    {
      sum += Ai[j    ] * x_[j    ]
           + Ai[j + 1] * x_[j + 1]
           + Ai[j + 2] * x_[j + 2]
           + Ai[j + 3] * x_[j + 3];
    }

    /* Remainder loop for any leftover elements (0 to 3). */
    for (; j < j_end; j++)
    {
      sum += Ai[j] * x_[j];
    }

    tmp_[i] = sum;
  }

  /* --------------------------------------------------------------------
   * Phase 2: y = A^T * tmp
   *   y[j] = sum_i A[i,j] * tmp[i]
   *
   * Instead of the original i-outer, j-inner order, we:
   *   - tile the j-dimension so each y-slice y[jj : jj+tile_j) stays
   *     in cache while all rows contribute to it;
   *   - for each j-tile, traverse A row-wise (i outer, j inner) so that
   *     A[i,*] is still accessed with unit stride.
   *
   * With y_ initialized to 0, the following is equivalent to the
   * original computation and preserves the per-j accumulation order
   * over i (0..M-1).
   * ------------------------------------------------------------------ */
  for (int jj = 0; jj < _PB_N; jj += tile_j)
  {
    int j_max = jj + tile_j;
    if (j_max > _PB_N)
      j_max = _PB_N;

    int len      = j_max - jj;
    int len_vec4 = len & ~3; /* multiple of 4 for unrolling */

    /* For this tile, we accumulate contributions from all rows i. */
    for (i = 0; i < _PB_M; i++)
    {
      const DATA_TYPE t_i = tmp_[i];
      const DATA_TYPE *restrict Ai = &A_[i][jj];

      int jloc = 0;

      /* Unrolled main loop over the current j-tile. */
      for (; jloc < len_vec4; jloc += 4)
      {
        y_[jj + jloc    ] += Ai[jloc    ] * t_i;
        y_[jj + jloc + 1] += Ai[jloc + 1] * t_i;
        y_[jj + jloc + 2] += Ai[jloc + 2] * t_i;
        y_[jj + jloc + 3] += Ai[jloc + 3] * t_i;
      }

      /* Remainder for the last 0–3 elements of the tile. */
      for (; jloc < len; jloc++)
      {
        y_[jj + jloc] += Ai[jloc] * t_i;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
