      x[i] = 1 + (i / fn);
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original mathematical computation:

     tmp[i] = sum_j A[i,j] * x[j]          (tmp = A * x)
     y[j]   = sum_i A[i,j] * tmp[i]        (y = A^T * tmp)

   which is implemented in the original PolyBench kernel as:

     for (i)
       y[i] = 0;
     for (i)
       tmp[i] = 0;
       for (j) tmp[i] += A[i][j] * x[j];
       for (j) y[j]   += A[i][j] * tmp[i];

   Optimizations applied here:

   - Keep the row-wise structure (i outer) to preserve good spatial locality
     on A (row-major).
   - Initialize y in a separate, simple loop over j (contiguous, easy to
     vectorize).
   - Use local, restrict-qualified aliases for A, x, y, tmp to improve
     the compiler's alias analysis and enable more aggressive vectorization.
   - Tile both i (rows) and j (columns) for better cache reuse:
       * TI: tile size in the row dimension.
       * TJ: tile size in the column / vector dimension.
     This improves locality of accesses to A, x and y for large problems.
   - Scalarize tmp[i] into a register 't' inside the i-loop, and write it
     to tmp[i] once per row. The y-update for that row then reuses 't'
     directly from registers instead of repeatedly loading tmp[i].
*/
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;
  int ii, jj;

  /* Tiling parameters.
     TI: number of rows processed together.
     TJ: number of columns (entries of x/y) processed per tile.

     These are chosen as small constants so that:
       - inner j-loops work on contiguous chunks, enabling good cache reuse
         and SIMD vectorization;
       - code size remains reasonable.
     They do not need to divide M or N; edge tiles are handled explicitly. */
  const int TI = 32;
  const int TJ = 256;

  /* Create restrict-qualified local aliases to help the compiler
     assume no aliasing between A, x, y, and tmp in this kernel. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

#pragma scop
  /* Initialize y to 0.0.
     Use j as the index since y is of length N. */
  for (j = 0; j < _PB_N; j++)
    y_[j] = SCALAR_VAL(0.0);

  /* Process the matrix by tiles of rows (ii..i_max-1) and all columns. */
  for (ii = 0; ii < _PB_M; ii += TI)
    {
      int i_max = (ii + TI < _PB_M) ? (ii + TI) : _PB_M;

      /* For each row i in this tile, compute:
           t      = sum_j A[i,j] * x[j]
           tmp[i] = t
           y[j]  += A[i,j] * t
         We tile the inner j-loop to improve cache locality on x and y. */
      for (i = ii; i < i_max; ++i)
        {
          DATA_TYPE t = SCALAR_VAL(0.0);

          /* First phase for this row: compute dot product t = A[i,*] · x. */
          for (jj = 0; jj < _PB_N; jj += TJ)
            {
              int j_max = (jj + TJ < _PB_N) ? (jj + TJ) : _PB_N;

              /* Inner-most loop over contiguous elements in j; good for SIMD. */
              for (j = jj; j < j_max; ++j)
                t += A_[i][j] * x_[j];
            }

          /* Store the computed tmp[i] to preserve original live-out semantics. */
          tmp_[i] = t;

          /* Second phase for this row: accumulate y += A^T * tmp using t. */
          for (jj = 0; jj < _PB_N; jj += TJ)
            {
              int j_max = (jj + TJ < _PB_N) ? (jj + TJ) : _PB_N;

              for (j = jj; j < j_max; ++j)
                y_[j] += A_[i][j] * t;
            }
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
