/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving original semantics):
   - Use local restrict-qualified pointers (x_, y_, tmp_) to aid the
     compiler in auto-vectorization by removing potential aliasing.
   - Scalarize tmp[i] into a local scalar 't' to keep it in registers
     for the whole i-iteration, and write back to tmp[i] only once.
     This removes repeated loads/stores of tmp[i].
   - Keep A's rows accessed through a row pointer (Ai) for better
     locality and clearer unit-stride access in the inner loops.
   - Manually unroll the inner loops over j by a small constant factor
     (4) to expose instruction-level parallelism and reduce loop
     overhead; the accumulation order over j is preserved.
*/
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Local restrict-qualified views to help the compiler with vectorization.
     By construction in PolyBench, these arrays do not alias. */
  DATA_TYPE *restrict x_   = x;
  DATA_TYPE *restrict y_   = y;
  DATA_TYPE *restrict tmp_ = tmp;

#pragma scop
  /* Initialization: identical semantics to the original
       for (i = 0; i < _PB_N; i++)
         y[i] = 0;
  */
  for (j = 0; j < _PB_N; j++)
    y_[j] = SCALAR_VAL(0.0);

  /* Main computation:
       for (i = 0; i < _PB_M; i++) {
         tmp[i] = 0;
         for (j = 0; j < _PB_N; j++)
           tmp[i] = tmp[i] + A[i][j] * x[j];
         for (j = 0; j < _PB_N; j++)
           y[j] = y[j] + A[i][j] * tmp[i];
       }
     We keep the same high-level schedule (row-wise, i outer) to preserve
     very good data locality on the row-major matrix A, but we:
       - keep tmp[i] in a scalar register 't',
       - use a row pointer Ai for contiguous access,
       - unroll the inner loops over j.
  */
  for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE t = SCALAR_VAL(0.0);
      /* Pointer to the beginning of row i of A. */
      DATA_TYPE *restrict Ai = &A[i][0];

      /* Compute t = sum_j A[i][j] * x[j] (dot product for row i). */
      int j_unroll = _PB_N & ~3; /* largest multiple of 4 <= _PB_N */

      /* Unrolled main part */
      for (j = 0; j < j_unroll; j += 4)
      {
        t += Ai[j]     * x_[j];
        t += Ai[j + 1] * x_[j + 1];
        t += Ai[j + 2] * x_[j + 2];
        t += Ai[j + 3] * x_[j + 3];
      }

      /* Remainder loop for N not divisible by 4 */
      for (; j < _PB_N; j++)
        t += Ai[j] * x_[j];

      /* Store the final value into tmp[i] (as in the original code). */
      tmp_[i] = t;

      /* y[j] += A[i][j] * t; uses the same row Ai and the scalar t.
         We again unroll by 4 while preserving the accumulation order. */
      j_unroll = _PB_N & ~3;

      for (j = 0; j < j_unroll; j += 4)
      {
        y_[j]     += Ai[j]     * t;
        y_[j + 1] += Ai[j + 1] * t;
        y_[j + 2] += Ai[j + 2] * t;
        y_[j + 3] += Ai[j + 3] * t;
      }

      for (; j < _PB_N; j++)
        y_[j] += Ai[j] * t;
    }
#pragma endscop

